//! Shared helpers for the fixture tests: fixture loading, the accuracy
//! metric, and lazily built diarizers.
#![allow(dead_code)]

use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::time::Instant;

use diarize::{
    DiarizeConfig, EmbeddingModel, SherpaDiarizer, SortformerDiarizer, SortformerPreset,
};
use meeting_core::{Diarizer, SpeakerTurn, SAMPLE_RATE};
use serde::Deserialize;

/// Fixtures generated by `testdata/generate.py` (gitignored); override with
/// `MEETING_TESTDATA`.
pub const DEFAULT_TESTDATA: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../testdata/audio");

pub fn testdata_dir() -> PathBuf {
    std::env::var_os("MEETING_TESTDATA")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from(DEFAULT_TESTDATA))
}

/// Models cache for tests: `DIARIZE_MODELS_DIR`, else
/// `~/Library/Caches/handy-meetings/diarize-models`.
pub fn models_dir() -> PathBuf {
    if let Some(d) = std::env::var_os("DIARIZE_MODELS_DIR") {
        return PathBuf::from(d);
    }
    let home = std::env::var_os("HOME").expect("HOME not set");
    PathBuf::from(home).join("Library/Caches/handy-meetings/diarize-models")
}

#[derive(Debug, Clone, Deserialize)]
pub struct TruthTurn {
    pub track: String,
    pub speaker: String,
    pub start_s: f64,
    pub end_s: f64,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Truth {
    pub scenario: String,
    pub duration_s: f64,
    pub turns: Vec<TruthTurn>,
}

pub struct Fixture {
    pub samples: Vec<f32>,
    pub truth: Vec<TruthTurn>,
}

impl Fixture {
    pub fn duration_s(&self) -> f64 {
        self.samples.len() as f64 / SAMPLE_RATE as f64
    }

    pub fn truth_speakers(&self) -> Vec<String> {
        let mut v: Vec<String> = Vec::new();
        for t in &self.truth {
            if !v.contains(&t.speaker) {
                v.push(t.speaker.clone());
            }
        }
        v
    }
}

/// Loads `<scenario>/<track>.wav` and the truth turns for that track.
/// Returns `None` (after printing why) when the fixture is missing.
pub fn load(scenario: &str, track: &str) -> Option<Fixture> {
    let dir = testdata_dir().join(scenario);
    let wav = dir.join(format!("{track}.wav"));
    let truth_path = dir.join("truth.json");
    if !wav.exists() || !truth_path.exists() {
        eprintln!(
            "SKIP: fixture {} missing. Generate fixtures with `python3 -I testdata/generate.py` \
             or set MEETING_TESTDATA.",
            wav.display()
        );
        return None;
    }
    let truth: Truth =
        serde_json::from_str(&std::fs::read_to_string(&truth_path).unwrap()).unwrap();
    Some(Fixture {
        samples: read_wav(&wav),
        truth: truth
            .turns
            .into_iter()
            .filter(|t| t.track == track)
            .collect(),
    })
}

fn read_wav(path: &Path) -> Vec<f32> {
    let mut r = hound::WavReader::open(path).unwrap();
    let spec = r.spec();
    assert_eq!(spec.sample_rate, SAMPLE_RATE, "{}", path.display());
    assert_eq!(spec.channels, 1, "{}", path.display());
    match spec.sample_format {
        hound::SampleFormat::Int => {
            let scale = (1i64 << (spec.bits_per_sample - 1)) as f32;
            r.samples::<i32>()
                .map(|s| s.unwrap() as f32 / scale)
                .collect()
        }
        hound::SampleFormat::Float => r.samples::<f32>().map(|s| s.unwrap()).collect(),
    }
}

/// Distinct speaker labels in the output.
pub fn speakers(turns: &[SpeakerTurn]) -> Vec<String> {
    let mut v: Vec<String> = Vec::new();
    for t in turns {
        if !v.contains(&t.speaker) {
            v.push(t.speaker.clone());
        }
    }
    v
}

pub struct Score {
    /// Fraction of truth speech time attributed to the right speaker after
    /// the best one-to-one cluster → speaker mapping. Missed speech counts as
    /// wrong.
    pub accuracy: f64,
    /// Fraction of truth speech not covered by any turn.
    pub missed: f64,
    /// Output speech time outside truth speech, relative to truth speech.
    pub false_alarm: f64,
    /// Best mapping truth speaker → output label.
    pub mapping: HashMap<String, String>,
}

const FRAME_S: f64 = 0.01;

pub fn score(truth: &[TruthTurn], turns: &[SpeakerTurn], duration_s: f64) -> Score {
    let n = (duration_s / FRAME_S).ceil() as usize + 1;
    let frame = |t: f64| ((t / FRAME_S).round().max(0.0) as usize).min(n);
    let truth_spk: Vec<String> = {
        let mut v: Vec<String> = Vec::new();
        for t in truth {
            if !v.contains(&t.speaker) {
                v.push(t.speaker.clone());
            }
        }
        v
    };
    let hyp_spk = speakers(turns);
    let mut t_lab: Vec<Option<usize>> = vec![None; n];
    for t in truth {
        let i = truth_spk.iter().position(|s| *s == t.speaker).unwrap();
        for f in &mut t_lab[frame(t.start_s)..frame(t.end_s)] {
            *f = Some(i);
        }
    }
    let mut h_lab: Vec<Option<usize>> = vec![None; n];
    for t in turns {
        let i = hyp_spk.iter().position(|s| *s == t.speaker).unwrap();
        for f in &mut h_lab[frame(t.start_s)..frame(t.end_s)] {
            *f = Some(i);
        }
    }
    let mut counts = vec![vec![0usize; hyp_spk.len()]; truth_spk.len()];
    let (mut total, mut missed, mut fa) = (0usize, 0usize, 0usize);
    for (t, h) in t_lab.iter().zip(&h_lab) {
        match (t, h) {
            (Some(t), Some(h)) => {
                total += 1;
                counts[*t][*h] += 1;
            }
            (Some(_), None) => {
                total += 1;
                missed += 1;
            }
            (None, Some(_)) => fa += 1,
            (None, None) => {}
        }
    }
    let (best, assign) = best_assignment(&counts, hyp_spk.len());
    let mapping = assign
        .iter()
        .enumerate()
        .filter_map(|(t, h)| h.map(|h| (truth_spk[t].clone(), hyp_spk[h].clone())))
        .collect();
    let denom = total.max(1) as f64;
    Score {
        accuracy: if total == 0 { 1.0 } else { best as f64 / denom },
        missed: missed as f64 / denom,
        false_alarm: fa as f64 / denom,
        mapping,
    }
}

/// Exhaustive one-to-one assignment (speaker counts here are tiny).
fn best_assignment(counts: &[Vec<usize>], n_hyp: usize) -> (usize, Vec<Option<usize>>) {
    fn go(
        t: usize,
        counts: &[Vec<usize>],
        used: &mut Vec<bool>,
        cur: &mut Vec<Option<usize>>,
        best: &mut (usize, Vec<Option<usize>>),
        acc: usize,
    ) {
        if t == counts.len() {
            if acc > best.0 || best.1.is_empty() {
                *best = (acc, cur.clone());
            }
            return;
        }
        cur.push(None);
        go(t + 1, counts, used, cur, best, acc);
        cur.pop();
        for h in 0..used.len() {
            if !used[h] {
                used[h] = true;
                cur.push(Some(h));
                go(t + 1, counts, used, cur, best, acc + counts[t][h]);
                cur.pop();
                used[h] = false;
            }
        }
    }
    let mut best = (0, Vec::new());
    go(
        0,
        counts,
        &mut vec![false; n_hyp],
        &mut Vec::new(),
        &mut best,
        0,
    );
    best
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Backend {
    /// Sortformer segmentation + sherpa-onnx speaker embeddings.
    Sortformer,
    /// sherpa-onnx pyannote + clustering + embeddings.
    Sherpa,
}

impl Backend {
    pub fn name(self) -> &'static str {
        match self {
            Backend::Sortformer => "sortformer",
            Backend::Sherpa => "sherpa",
        }
    }
}

/// Base config for tests. For experiments, `DIARIZE_EMBEDDING_MODEL` and
/// `DIARIZE_CLUSTERING_MODEL` (an `EmbeddingModel::id`) and
/// `DIARIZE_THRESHOLD` override the defaults; `DIARIZE_NO_EMBEDDINGS=1`
/// turns per-speaker embeddings off (to time segmentation alone).
pub fn config() -> DiarizeConfig {
    let mut c = DiarizeConfig::new(models_dir());
    if let Ok(id) = std::env::var("DIARIZE_EMBEDDING_MODEL") {
        c.embedding_model = EmbeddingModel::from_id(&id)
            .unwrap_or_else(|| panic!("unknown DIARIZE_EMBEDDING_MODEL {id}"));
    }
    if let Ok(id) = std::env::var("DIARIZE_CLUSTERING_MODEL") {
        c.clustering_model = EmbeddingModel::from_id(&id)
            .unwrap_or_else(|| panic!("unknown DIARIZE_CLUSTERING_MODEL {id}"));
    }
    if std::env::var_os("DIARIZE_NO_EMBEDDINGS").is_some() {
        c.speaker_embeddings = false;
    }
    if let Ok(t) = std::env::var("DIARIZE_THRESHOLD") {
        c.cluster_threshold = t.parse().expect("DIARIZE_THRESHOLD");
    }
    c
}

/// A fresh diarizer per call. Not cached in a static: ggml-metal asserts at
/// process exit when a Metal-backed model is still alive then.
pub fn diarizer(b: Backend) -> Box<dyn Diarizer> {
    match b {
        Backend::Sortformer => {
            let d = SortformerDiarizer::new(config()).expect("load Sortformer diarizer");
            // DIARIZE_SORTFORMER_PRESET=default|very_high|high|low for experiments.
            Box::new(
                match std::env::var("DIARIZE_SORTFORMER_PRESET").as_deref() {
                    Ok("default") => d.with_preset(None),
                    Ok("very_high") => d.with_preset(Some(SortformerPreset::VeryHighLatency)),
                    Ok("high") => d.with_preset(Some(SortformerPreset::HighLatency)),
                    Ok("low") => d.with_preset(Some(SortformerPreset::LowLatency)),
                    Ok(other) => panic!("unknown DIARIZE_SORTFORMER_PRESET {other}"),
                    Err(_) => d,
                },
            )
        }
        Backend::Sherpa => Box::new(SherpaDiarizer::new(config()).expect("load sherpa diarizer")),
    }
}

pub struct Run {
    pub turns: Vec<SpeakerTurn>,
    pub seconds: f64,
}

pub fn run_with(d: &dyn Diarizer, fx: &Fixture) -> Run {
    let t0 = Instant::now();
    let turns = d.diarize(&fx.samples).expect("diarize");
    Run {
        turns,
        seconds: t0.elapsed().as_secs_f64(),
    }
}

pub fn run(b: Backend, fx: &Fixture) -> Run {
    run_with(diarizer(b).as_ref(), fx)
}

/// Checks the `Diarizer` contract on any output.
pub fn assert_contract(turns: &[SpeakerTurn], duration_s: f64) {
    for t in turns {
        assert!(t.start_s >= 0.0 && t.end_s > t.start_s, "{t:?}");
        assert!(t.end_s <= duration_s + 0.05, "{t:?} beyond {duration_s}");
        assert!(t.speaker.starts_with('S'), "{t:?}");
        if let Some(e) = &t.embedding {
            let norm: f32 = e.iter().map(|x| x * x).sum::<f32>().sqrt();
            assert!(
                (norm - 1.0).abs() < 1e-3,
                "embedding not normalised: {norm}"
            );
        }
    }
    for w in turns.windows(2) {
        assert!(
            w[0].end_s <= w[1].start_s + 1e-9,
            "overlap: {:?} {:?}",
            w[0],
            w[1]
        );
    }
}

const GAP_S: f64 = 0.7;

/// Builds a recording from truth turns of existing fixtures: each piece is
/// (scenario, track, truth label, nth turn of that label, new label). Pieces
/// are laid end to end with 0.7 s of silence, like `generate.py` does.
pub fn splice(pieces: &[(&str, &str, &str, usize, &str)]) -> Option<Fixture> {
    let mut samples = vec![0.0f32; (GAP_S * SAMPLE_RATE as f64) as usize];
    let mut truth = Vec::new();
    for (scenario, track, label, nth, new_label) in pieces {
        let fx = load(scenario, track)?;
        let t = fx
            .truth
            .iter()
            .filter(|t| t.speaker == *label)
            .nth(*nth)
            .unwrap_or_else(|| panic!("{scenario}/{track}: no turn {nth} of {label}"));
        let i0 = (t.start_s * SAMPLE_RATE as f64) as usize;
        let i1 = ((t.end_s * SAMPLE_RATE as f64) as usize).min(fx.samples.len());
        let start = samples.len() as f64 / SAMPLE_RATE as f64;
        samples.extend_from_slice(&fx.samples[i0..i1]);
        truth.push(TruthTurn {
            track: track.to_string(),
            speaker: new_label.to_string(),
            start_s: start,
            end_s: start + (i1 - i0) as f64 / SAMPLE_RATE as f64,
        });
        samples.extend(std::iter::repeat_n(
            0.0,
            (GAP_S * SAMPLE_RATE as f64) as usize,
        ));
    }
    Some(Fixture { samples, truth })
}

/// (scenario, track, [(old label, new label)]).
pub type ConcatPiece<'a> = (&'a str, &'a str, &'a [(&'a str, &'a str)]);

/// Whole fixture tracks one after another, truth labels renamed per piece.
pub fn concat(pieces: &[ConcatPiece]) -> Option<Fixture> {
    let mut samples = Vec::new();
    let mut truth = Vec::new();
    for (scenario, track, rename) in pieces {
        let fx = load(scenario, track)?;
        let offset = samples.len() as f64 / SAMPLE_RATE as f64;
        for t in &fx.truth {
            let speaker = rename
                .iter()
                .find(|(old, _)| *old == t.speaker)
                .map(|(_, new)| new.to_string())
                .unwrap_or_else(|| t.speaker.clone());
            truth.push(TruthTurn {
                track: t.track.clone(),
                speaker,
                start_s: t.start_s + offset,
                end_s: t.end_s + offset,
            });
        }
        samples.extend_from_slice(&fx.samples);
    }
    Some(Fixture { samples, truth })
}

/// Derived scenarios built from the generated fixtures.
///
/// - `three_distinct`: three clearly different voices on one track (Eddy,
///   Flo, Daniel). `three_remote` cannot test three speakers fairly because
///   its Eddy and Reed TTS voices are near identical (see `voice_similarity`).
/// - `long_mix`: ~3.3 min alternating `de_two` and `de_en_mixed` (Anna,
///   Eddy, Daniel), to check that speaker identities hold across a longer
///   recording (Sortformer is a streaming model with a speaker cache).
pub fn derived(name: &str) -> Option<Fixture> {
    match name {
        "three_distinct" => splice(&[
            ("three_remote", "system", "R1", 0, "Eddy"),
            ("three_remote", "system", "R2", 0, "Flo"),
            ("de_en_mixed", "mic", "B", 0, "Daniel"),
            ("three_remote", "system", "R1", 1, "Eddy"),
            ("de_en_mixed", "mic", "B", 1, "Daniel"),
            ("three_remote", "system", "R2", 1, "Flo"),
            ("de_en_mixed", "mic", "B", 2, "Daniel"),
        ]),
        "long_mix" => {
            let two: &[(&str, &str)] = &[("A", "Anna"), ("B", "Eddy")];
            let mixed: &[(&str, &str)] = &[("A", "Anna"), ("B", "Daniel")];
            concat(&[
                ("de_two", "mic", two),
                ("de_en_mixed", "mic", mixed),
                ("de_two", "mic", two),
                ("de_en_mixed", "mic", mixed),
                ("de_two", "mic", two),
            ])
        }
        _ => panic!("unknown derived scenario {name}"),
    }
}

/// A fixture by name: `<scenario>/<track>` from disk, or a derived one.
pub fn fixture(scenario: &str, track: &str) -> Option<Fixture> {
    match scenario {
        "three_distinct" | "long_mix" => derived(scenario),
        _ => load(scenario, track),
    }
}
